script:
$ProgressPreference = 'SilentlyContinue'
$ErrorActionPreference = 'Stop'
$receipt = '\\wsl.localhost\Ubuntu\tmp\src001-vm-7a772f0\hyperv-enablement.json'
$logPath = '\\wsl.localhost\Ubuntu\tmp\src001-vm-7a772f0\hyperv-enablement-dism.log'
$featureNames = @('Microsoft-Hyper-V-Hypervisor','Microsoft-Hyper-V-Services','Microsoft-Hyper-V-Management-PowerShell')
function Snapshot {
 [ordered]@{
  utc=[DateTime]::UtcNow.ToString('o')
  features=@(Get-WindowsOptionalFeature -Online | Where-Object { $_.FeatureName -match 'Hyper-V|HypervisorPlatform|VirtualMachinePlatform|Subsystem-Linux' } | Select-Object FeatureName,@{Name='State';Expression={$_.State.ToString()}})
  services=@(Get-Service vmms,vmcompute -ErrorAction SilentlyContinue | Select-Object Name,@{Name='Status';Expression={$_.Status.ToString()}},@{Name='StartType';Expression={$_.StartType.ToString()}})
  adapters=@(Get-NetAdapter -IncludeHidden | Select-Object Name,InterfaceDescription,InterfaceGuid,ifIndex,@{Name='Status';Expression={$_.Status.ToString()}})
 }
}
$r=[ordered]@{
 operation='ENABLE_MINIMAL_HYPERV_FACILITY_COMPONENTS'
 provisioning_id='VM-PREP-SRC001-20260915-7a772f0'
 authority_commit='7a772f03492d5f76ccb238b69883f5a83c295695'
 command='Enable-WindowsOptionalFeature -Online -FeatureName Microsoft-Hyper-V-Hypervisor,Microsoft-Hyper-V-Services,Microsoft-Hyper-V-Management-PowerShell -All -NoRestart -LimitAccess -LogPath <task DISM log>'
 target=$featureNames
 administrator=([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
 reboot_performed=$false
 started_utc=[DateTime]::UtcNow.ToString('o')
 status='BEFORE_OPERATION'
}
try {
 $r.before=Snapshot
 $r | ConvertTo-Json -Depth 12 | Set-Content -LiteralPath $receipt -Encoding UTF8
 foreach($feature in $featureNames) {
   if(($r.before.features | Where-Object {$_.FeatureName -eq $feature}).State -ne 'Disabled') { throw "Pinned prior feature state changed: $feature" }
 }
 $r.result=Enable-WindowsOptionalFeature -Online -FeatureName $featureNames -All -NoRestart -LimitAccess -LogPath $logPath | Select-Object Online,RestartNeeded,Path
 $r.status='COMMAND_SUCCEEDED'
 $r.exit=0
} catch { $r.status='COMMAND_FAILED';$r.error=$_.Exception.Message;$r.exit=1 }
try { $r.after=Snapshot } catch { $r.after_error=$_.Exception.Message }
$r.finished_utc=[DateTime]::UtcNow.ToString('o')
$r.rollback='No rollback performed. Prior states are retained. Disabling newly enabled Hyper-V components is a separate disruptive operation requiring impact review and may require reboot; do not disable WSL or VirtualMachinePlatform.'
$r | ConvertTo-Json -Depth 12 | Set-Content -LiteralPath $receipt -Encoding UTF8
